// kernel/src/font.rs — растровый шрифт консоли (ASCII + кириллица).
//
// СГЕНЕРИРОВАНО автоматически: tools/gen-font8x16.ps1
// Источник: PT Mono Regular (PTM55FT.ttf), ParaType, SIL Open Font License 1.1.
// Лицензия: см. assets/fonts/OFL-PT-Mono.txt. Шрифт растрирован в сетку 8x16
// без сглаживания (SingleBitPerPixelGridFit), по одному u16 на строку (10 пикселей),
// MSB — левый пиксель. Это терминальный шрифт консоли (D-011: PT Mono).
//
// Не редактировать вручную: перегенерировать скриптом.

pub const GLYPH_W: usize = 10;
pub const GLYPH_H: usize = 16;

const ASCII_FIRST: u32 = 0x20;
const ASCII_LAST: u32 = 0x7E;
const CYR_FIRST: u32 = 0x0410;
const CYR_LAST: u32 = 0x044F;
const ASCII_COUNT: usize = 95;

/// Индекс глифа в GLYPHS. Неизвестный символ отображается как '?'.
pub fn glyph_index(c: char) -> usize {
    let u = c as u32;
    if (ASCII_FIRST..=ASCII_LAST).contains(&u) {
        return (u - ASCII_FIRST) as usize;
    }
    if (CYR_FIRST..=CYR_LAST).contains(&u) {
        return ASCII_COUNT + (u - CYR_FIRST) as usize;
    }
    match u {
        0x0401 => ASCII_COUNT + 64, // Ё
        0x0451 => ASCII_COUNT + 65, // ё
        0x2013 => ASCII_COUNT + 66, // –
        0x2014 => ASCII_COUNT + 67, // —
        0x00AB => ASCII_COUNT + 68, // «
        0x00BB => ASCII_COUNT + 69, // »
        _ => ('?' as u32 - ASCII_FIRST) as usize,
    }
}

